// @domain: awareness
//! Who is calling (#4478 door rules, part 1). Every write names a signed caller: an
//! ES256 token from the identity issuer, checked by the one shared verifier
//! (chorus-oidc), with the caller's principal and write grants read from the model.
//! Generated by athena-gen from its template — DO NOT EDIT; change the generator.

use chorus_oidc::auth::AuthError;
use chorus_oidc::oidc::{self, OidcVerifier};

pub struct Caller {
    pub principal: String,
    pub web_id: String,
    pub scopes: Vec<String>,
}

pub struct Auth {
    verifier: OidcVerifier,
}

fn now() -> u64 {
    std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_secs()).unwrap_or(0)
}

/// `query` runs one SPARQL SELECT against the model's identity graphs and returns the
/// SPARQL-JSON body, or None when the store cannot answer (the verifier fails closed).
pub fn build(issuer: &str, query: impl Fn(&str) -> Option<String> + Clone + Send + Sync + 'static) -> Auth {
    let jwks = format!("{}/.oidc/jwks", issuer.trim_end_matches('/'));
    oidc::prime_allow_set_graph(query.clone());
    let (q1, q2, q3, q4) = (query.clone(), query.clone(), query.clone(), query);
    let verifier = OidcVerifier::new(
        issuer,
        move || oidc::resolve_principal_webids(&q1),
        move || oidc::resolve_principal_roles(&q2),
        move || oidc::resolve_principal_scopes(&q3),
        move || ureq::get(&jwks).timeout(std::time::Duration::from_secs(3)).call().ok()?.into_string().ok(),
    )
    .with_principal_names(move || oidc::resolve_principal_names(&q4));
    Auth { verifier }
}

/// The refusal a caller gets, typed: 401 when we cannot tell who you are, 403 when we
/// can and you may not.
pub fn refusal(e: &AuthError) -> (u16, &'static str) {
    match e {
        AuthError::Missing => (401, "no-token"),
        AuthError::Hs256Retired => (401, "token-retired"),
        AuthError::Malformed | AuthError::BadSignature | AuthError::UnknownAlg | AuthError::IssuerMismatch => (401, "token-invalid"),
        AuthError::Expired => (401, "token-expired"),
        AuthError::WrongAudience => (401, "token-wrong-audience"),
        AuthError::JwksUnreachable => (503, "identity-unreachable"),
        AuthError::WebIdNotAllowed => (403, "not-a-principal"),
    }
}

impl Auth {
    pub fn caller(&self, authorization: Option<&str>) -> Result<Caller, AuthError> {
        let token = authorization.and_then(|h| h.strip_prefix("Bearer ")).unwrap_or("");
        let t = now();
        let claims = oidc::verify_any(token, &self.verifier, t)?;
        let principal = self.verifier.principal_for(&claims.web_id, t).unwrap_or_else(|| claims.agent_id.clone());
        let scopes = self.verifier.scopes_for(&claims.web_id, t);
        Ok(Caller { principal, web_id: claims.web_id, scopes })
    }
}
